window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e2f7c8e893c8483c"]={"versions": [{"id": "FIG-e2f7c8e893c8483c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Netzwerk- und Deployment-Topologiediagramm (High-Level System Deployment View).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung der Einsatz- und Vernetzungsszenarien des FlexRay ISO Transport Layers (<code>FrTp</code>, spezifiziert nach ISO 10681-2) im AUTOSAR-Gesamtsystem.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Das Schaubild veranschaulicht die Multi-Knoten-Kommunikation über einen gemeinsamen FlexRay-Kommunikationscluster (Kanal A/B).</li>\n<li>Ein zentrales <strong>Gateway-Steuergerät</strong> bindet heterogene Bordnetz-Bussysteme (angedeutet an der linken Schnittstelle, typischerweise Ethernet/DoIP, CAN/CanTp, weitere FlexRay-Zweige) an und fungiert über die <code>PduR</code> (PDU Router) als zentraler Vermittlungsknoten für transportierte Diagnosedaten (UDS nach ISO 14229-2/-4) oder Flash-/Software-Update-Container.</li>\n<li>Die Steuergeräte <strong><code>ECU 1</code> bis <code>ECU n</code></strong> bilden die transportprotokoll-terminierenden Endpunkte am FlexRay-Bus.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten & BSW-Module:</strong></li>\n<li><strong>Gateway:</strong> Zentrales Steuergerät mit Multibus-Anbindung. Beherbergt einen Multi-Channel-fähigen <code>FrTp</code>-Stack sowie PduR-Routingpfade zwischen FrTp und Fremdbus-Transportprotokollen (z. B. <code>DoIP</code> oder <code>CanTp</code>).</li>\n<li><strong>ECU 1, ECU 2, ECU n:</strong> Unabhängige FlexRay-Teilnehmer (Subsysteme/Sensoren/Aktoren), die jeweils eine lokale <code>FrTp</code>-Modulinstanz zur Terminierung von TP-Verbindungen ausführen.</li>\n<li><strong>FlexRay-Bus:</strong> Physikalischer Übertragungskanal (Shared Medium, statisches und/oder dynamisches Segment gemäß FlexRay-Kommunikationszyklus).</li>\n<li><strong>Schnittstellen & Kopplung der FrTp-Module:</strong></li>\n<li><strong>Obere Schnittstelle (PduR-Kopplung):</strong></li>\n<li>Sendepfad: <code>PduR_FrTpTransmit()</code>, <code>PduR_FrTpCopyTxData()</code>, <code>PduR_FrTpTxConfirmation()</code>.</li>\n<li>Empfangspfad: <code>PduR_FrTpStartOfReception()</code>, <code>PduR_FrTpCopyRxData()</code>, <code>PduR_FrTpRxIndication()</code>.</li>\n<li><strong>Untere Schnittstelle (FrIf-Kopplung):</strong></li>\n<li>Sendepfad: <code>FrIf_Transmit()</code>, <code>FrIf_CancelTransmit()</code>.</li>\n<li>Empfangspfad / Callbacks: <code>FrTp_RxIndication()</code>, <code>FrTp_TxConfirmation()</code>, <code>FrTp_TriggerTransmit()</code>.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Topologie:</strong> $1 : n$-Verbindung (1 Gateway bedient $n$ ECUs über einen gemeinsamen FlexRay-Cluster).</li>\n<li><strong>Kommunikationsbeziehungen:</strong></li>\n<li>Punkt-zu-Punkt (1:1 Unicast) für physikalische Adressierung (z. B. gezieltes Flashen von <code>ECU 1</code>).</li>\n<li>Punkt-zu-Mehrpunkt (1:n Multicast/Broadcast) für funktionale Adressierung (z. B. simultaner Diagnosestatus/TesterPresent an <code>ECU 1..n</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>End-to-End Routing-Szenario (Gateway $\\rightarrow$ ECU x):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Routing-Trigger:</strong> Gateway empfängt eine segmentierte Großnachricht über ein externes Interface (z. B. DoIP via Ethernet).</li>\n<li><strong>Inter-Module Buffering:</strong> <code>PduR</code> im Gateway initiiert via <code>FrTp_Transmit()</code> den Sendeprozess auf dem FlexRay-Zweig und puffert/streamt Nutzdaten über <code>PduR_FrTpCopyTxData()</code>.</li>\n<li><strong>ISO 10681-2 Frame-Generierung:</strong> <code>FrTp</code> fragmentiert die N-SDU in N-PDUs:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Start Frame (SF) bei unsegmentierten Nachrichten.</li>\n<li>First Frame (FF) gefolgt von Consecutive Frames (CF) bei segmentiertem Transfer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfang & Flow Control:</strong> Ziel-ECU (z. B. <code>ECU 1</code>) signalisiert über <code>FrTp_RxIndication()</code> den Eingang, reserviert Puffer über <code>PduR_FrTpStartOfReception()</code> und antwortet bei Bedarf mit Flow Control Frames (FC: CTS, WT, OVFLW) an das Gateway.</li>\n<li><strong>Quittierung:</strong> Nach erfolgreichem Empfang aller CFs meldet <code>FrTp</code> via <code>PduR_FrTpRxIndication(E_OK)</code> den Abschluss an die Diagnose-Applikation (<code>Dcm</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Parallelität & Timer-Überwachung:</strong></li>\n<li>Das Gateway-FrTp betreibt parallele Verbindungszustandsautomaten (Connection Channels), um mehrere ECUs simultan zu bedienen.</li>\n<li>ISO 10681-2 Timer ($A_s$, $A_r$, $B_s$, $B_r$, $C_r$) laufen pro aktivem Kanal autark. Bei Timeout erfolgt der synchrone Verbindungsabbruch und die Fehlermeldung <code>PduR_FrTpRxIndication(E_NOT_OK)</code> bzw. <code>PduR_FrTpTxConfirmation(E_NOT_OK)</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Routing-Architektur (<code>PduR</code> / Gateway-Konfiguration):</strong></li>\n<li>Das Gateway muss für paralleles Flashen (<code>Parallel Diagnostic Flashing</code>) konfiguriert sein. Hierfür sind in der Ecuc des Gateways ausreichend viele parallele Kanäle (<code>FrTpNumberOfChannels</code>) und FIFO-/Gateway-Buffer in der <code>PduR</code> vorzuhalten.</li>\n<li><strong>FlexRay-Slot-Allokation (FrIf / Fibex / ARXML):</strong></li>\n<li><code>FrTp</code>-PDUs werden bevorzugt im <strong>dynamischen Segment</strong> des FlexRay-Zyklus über Minislots übertragen, um Bandbreite bedarfsgerecht zuzuweisen, ohne die zyklisch-deterministischen Signale im statischen Segment zu stören.</li>\n<li>Werden statische Slots genutzt, müssen diese für TP exklusiv oder im PDU-Multiplexing reserviert werden.</li>\n<li><strong>Konfigurationsasymmetrie (Gateway vs. Sub-ECUs):</strong></li>\n<li><em>Gateway:</em> Erfordert maximale Pufferkapazität, hohe Kanalanzahl und Reentrancy-Handling für asynchrone Tx/Rx-Transaktionen auf mehreren logischen Kanälen.</li>\n<li><em>ECU 1..n:</em> Zur Ressourceneinsparung auf End-Steuergeräten genügen meist minimal konfigurierte <code>FrTp</code>-Instanzen (Single-Channel oder Dual-Channel für gleichzeitige funktionale und physikalische Diagnoseverbindungen).</li>\n<li><strong>ISO 10681-2 Adressierungs-Parameter:</strong></li>\n<li>Konfiguration von <code>FrTpNode</code> und <code>FrTpConnection</code> erfordert eindeutige Zuordnungen von Local- und Remote-Addresses sowie korrekte Abstimmung von Block Size ($BS$) und Separation Time ($ST_{min}$ bzw. Bandwidth Control $BC$).</li>\n</ul>"}, {"id": "FIG-ad6a3a0d1fec0690", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Netzwerk- und Deployment-Topologiediagramm (High-Level System Deployment View).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung der Einsatz- und Vernetzungsszenarien des FlexRay ISO Transport Layers (<code>FrTp</code>, spezifiziert nach ISO 10681-2) im AUTOSAR-Gesamtsystem.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Das Schaubild veranschaulicht die Multi-Knoten-Kommunikation über einen gemeinsamen FlexRay-Kommunikationscluster (Kanal A/B).</li>\n<li>Ein zentrales <strong>Gateway-Steuergerät</strong> bindet heterogene Bordnetz-Bussysteme (angedeutet an der linken Schnittstelle, typischerweise Ethernet/DoIP, CAN/CanTp, weitere FlexRay-Zweige) an und fungiert über die <code>PduR</code> (PDU Router) als zentraler Vermittlungsknoten für transportierte Diagnosedaten (UDS nach ISO 14229-2/-4) oder Flash-/Software-Update-Container.</li>\n<li>Die Steuergeräte <strong><code>ECU 1</code> bis <code>ECU n</code></strong> bilden die transportprotokoll-terminierenden Endpunkte am FlexRay-Bus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten & BSW-Module:</strong></li>\n<li><strong>Gateway:</strong> Zentrales Steuergerät mit Multibus-Anbindung. Beherbergt einen Multi-Channel-fähigen <code>FrTp</code>-Stack sowie PduR-Routingpfade zwischen FrTp und Fremdbus-Transportprotokollen (z. B. <code>DoIP</code> oder <code>CanTp</code>).</li>\n<li><strong>ECU 1, ECU 2, ECU n:</strong> Unabhängige FlexRay-Teilnehmer (Subsysteme/Sensoren/Aktoren), die jeweils eine lokale <code>FrTp</code>-Modulinstanz zur Terminierung von TP-Verbindungen ausführen.</li>\n<li><strong>FlexRay-Bus:</strong> Physikalischer Übertragungskanal (Shared Medium, statisches und/oder dynamisches Segment gemäß FlexRay-Kommunikationszyklus).</li>\n<li><strong>Schnittstellen & Kopplung der FrTp-Module:</strong></li>\n<li><strong>Obere Schnittstelle (PduR-Kopplung):</strong></li>\n<li>Sendepfad: <code>PduR_FrTpTransmit()</code>, <code>PduR_FrTpCopyTxData()</code>, <code>PduR_FrTpTxConfirmation()</code>.</li>\n<li>Empfangspfad: <code>PduR_FrTpStartOfReception()</code>, <code>PduR_FrTpCopyRxData()</code>, <code>PduR_FrTpRxIndication()</code>.</li>\n<li><strong>Untere Schnittstelle (FrIf-Kopplung):</strong></li>\n<li>Sendepfad: <code>FrIf_Transmit()</code>, <code>FrIf_CancelTransmit()</code>.</li>\n<li>Empfangspfad / Callbacks: <code>FrTp_RxIndication()</code>, <code>FrTp_TxConfirmation()</code>, <code>FrTp_TriggerTransmit()</code>.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Topologie:</strong> $1 : n$-Verbindung (1 Gateway bedient $n$ ECUs über einen gemeinsamen FlexRay-Cluster).</li>\n<li><strong>Kommunikationsbeziehungen:</strong></li>\n<li>Punkt-zu-Punkt (1:1 Unicast) für physikalische Adressierung (z. B. gezieltes Flashen von <code>ECU 1</code>).</li>\n<li>Punkt-zu-Mehrpunkt (1:n Multicast/Broadcast) für funktionale Adressierung (z. B. simultaner Diagnosestatus/TesterPresent an <code>ECU 1..n</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>End-to-End Routing-Szenario (Gateway $\\rightarrow$ ECU x):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Routing-Trigger:</strong> Gateway empfängt eine segmentierte Großnachricht über ein externes Interface (z. B. DoIP via Ethernet).</li>\n<li><strong>Inter-Module Buffering:</strong> <code>PduR</code> im Gateway initiiert via <code>FrTp_Transmit()</code> den Sendeprozess auf dem FlexRay-Zweig und puffert/streamt Nutzdaten über <code>PduR_FrTpCopyTxData()</code>.</li>\n<li><strong>ISO 10681-2 Frame-Generierung:</strong> <code>FrTp</code> fragmentiert die N-SDU in N-PDUs:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Start Frame (SF) bei unsegmentierten Nachrichten.</li>\n<li>First Frame (FF) gefolgt von Consecutive Frames (CF) bei segmentiertem Transfer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfang & Flow Control:</strong> Ziel-ECU (z. B. <code>ECU 1</code>) signalisiert über <code>FrTp_RxIndication()</code> den Eingang, reserviert Puffer über <code>PduR_FrTpStartOfReception()</code> und antwortet bei Bedarf mit Flow Control Frames (FC: CTS, WT, OVFLW) an das Gateway.</li>\n<li><strong>Quittierung:</strong> Nach erfolgreichem Empfang aller CFs meldet <code>FrTp</code> via <code>PduR_FrTpRxIndication(E_OK)</code> den Abschluss an die Diagnose-Applikation (<code>Dcm</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Parallelität & Timer-Überwachung:</strong></li>\n<li>Das Gateway-FrTp betreibt parallele Verbindungszustandsautomaten (Connection Channels), um mehrere ECUs simultan zu bedienen.</li>\n<li>ISO 10681-2 Timer ($A_s$, $A_r$, $B_s$, $B_r$, $C_r$) laufen pro aktivem Kanal autark. Bei Timeout erfolgt der synchrone Verbindungsabbruch und die Fehlermeldung <code>PduR_FrTpRxIndication(E_NOT_OK)</code> bzw. <code>PduR_FrTpTxConfirmation(E_NOT_OK)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Routing-Architektur (<code>PduR</code> / Gateway-Konfiguration):</strong></li>\n<li>Das Gateway muss für paralleles Flashen (<code>Parallel Diagnostic Flashing</code>) konfiguriert sein. Hierfür sind in der Ecuc des Gateways ausreichend viele parallele Kanäle (<code>FrTpNumberOfChannels</code>) und FIFO-/Gateway-Buffer in der <code>PduR</code> vorzuhalten.</li>\n<li><strong>FlexRay-Slot-Allokation (FrIf / Fibex / ARXML):</strong></li>\n<li><code>FrTp</code>-PDUs werden bevorzugt im <strong>dynamischen Segment</strong> des FlexRay-Zyklus über Minislots übertragen, um Bandbreite bedarfsgerecht zuzuweisen, ohne die zyklisch-deterministischen Signale im statischen Segment zu stören.</li>\n<li>Werden statische Slots genutzt, müssen diese für TP exklusiv oder im PDU-Multiplexing reserviert werden.</li>\n<li><strong>Konfigurationsasymmetrie (Gateway vs. Sub-ECUs):</strong></li>\n<li><em>Gateway:</em> Erfordert maximale Pufferkapazität, hohe Kanalanzahl und Reentrancy-Handling für asynchrone Tx/Rx-Transaktionen auf mehreren logischen Kanälen.</li>\n<li><em>ECU 1..n:</em> Zur Ressourceneinsparung auf End-Steuergeräten genügen meist minimal konfigurierte <code>FrTp</code>-Instanzen (Single-Channel oder Dual-Channel für gleichzeitige funktionale und physikalische Diagnoseverbindungen).</li>\n<li><strong>ISO 10681-2 Adressierungs-Parameter:</strong></li>\n<li>Konfiguration von <code>FrTpNode</code> und <code>FrTpConnection</code> erfordert eindeutige Zuordnungen von Local- und Remote-Addresses sowie korrekte Abstimmung von Block Size ($BS$) und Separation Time ($ST_{min}$ bzw. Bandwidth Control $BC$).</li>\n</ul>"}, {"id": "FIG-4cced100e5287ece", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Netzwerk- und Deployment-Topologiediagramm (High-Level System Deployment View).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung der Einsatz- und Vernetzungsszenarien des FlexRay ISO Transport Layers (<code>FrTp</code>, spezifiziert nach ISO 10681-2) im AUTOSAR-Gesamtsystem.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Das Schaubild veranschaulicht die Multi-Knoten-Kommunikation über einen gemeinsamen FlexRay-Kommunikationscluster (Kanal A/B).</li>\n<li>Ein zentrales <strong>Gateway-Steuergerät</strong> bindet heterogene Bordnetz-Bussysteme (angedeutet an der linken Schnittstelle, typischerweise Ethernet/DoIP, CAN/CanTp, weitere FlexRay-Zweige) an und fungiert über die <code>PduR</code> (PDU Router) als zentraler Vermittlungsknoten für transportierte Diagnosedaten (UDS nach ISO 14229-2/-4) oder Flash-/Software-Update-Container.</li>\n<li>Die Steuergeräte <strong><code>ECU 1</code> bis <code>ECU n</code></strong> bilden die transportprotokoll-terminierenden Endpunkte am FlexRay-Bus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten & BSW-Module:</strong></li>\n<li><strong>Gateway:</strong> Zentrales Steuergerät mit Multibus-Anbindung. Beherbergt einen Multi-Channel-fähigen <code>FrTp</code>-Stack sowie PduR-Routingpfade zwischen FrTp und Fremdbus-Transportprotokollen (z. B. <code>DoIP</code> oder <code>CanTp</code>).</li>\n<li><strong>ECU 1, ECU 2, ECU n:</strong> Unabhängige FlexRay-Teilnehmer (Subsysteme/Sensoren/Aktoren), die jeweils eine lokale <code>FrTp</code>-Modulinstanz zur Terminierung von TP-Verbindungen ausführen.</li>\n<li><strong>FlexRay-Bus:</strong> Physikalischer Übertragungskanal (Shared Medium, statisches und/oder dynamisches Segment gemäß FlexRay-Kommunikationszyklus).</li>\n<li><strong>Schnittstellen & Kopplung der FrTp-Module:</strong></li>\n<li><strong>Obere Schnittstelle (PduR-Kopplung):</strong></li>\n<li>Sendepfad: <code>PduR_FrTpTransmit()</code>, <code>PduR_FrTpCopyTxData()</code>, <code>PduR_FrTpTxConfirmation()</code>.</li>\n<li>Empfangspfad: <code>PduR_FrTpStartOfReception()</code>, <code>PduR_FrTpCopyRxData()</code>, <code>PduR_FrTpRxIndication()</code>.</li>\n<li><strong>Untere Schnittstelle (FrIf-Kopplung):</strong></li>\n<li>Sendepfad: <code>FrIf_Transmit()</code>, <code>FrIf_CancelTransmit()</code>.</li>\n<li>Empfangspfad / Callbacks: <code>FrTp_RxIndication()</code>, <code>FrTp_TxConfirmation()</code>, <code>FrTp_TriggerTransmit()</code>.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Topologie:</strong> $1 : n$-Verbindung (1 Gateway bedient $n$ ECUs über einen gemeinsamen FlexRay-Cluster).</li>\n<li><strong>Kommunikationsbeziehungen:</strong></li>\n<li>Punkt-zu-Punkt (1:1 Unicast) für physikalische Adressierung (z. B. gezieltes Flashen von <code>ECU 1</code>).</li>\n<li>Punkt-zu-Mehrpunkt (1:n Multicast/Broadcast) für funktionale Adressierung (z. B. simultaner Diagnosestatus/TesterPresent an <code>ECU 1..n</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>End-to-End Routing-Szenario (Gateway $\\rightarrow$ ECU x):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Routing-Trigger:</strong> Gateway empfängt eine segmentierte Großnachricht über ein externes Interface (z. B. DoIP via Ethernet).</li>\n<li><strong>Inter-Module Buffering:</strong> <code>PduR</code> im Gateway initiiert via <code>FrTp_Transmit()</code> den Sendeprozess auf dem FlexRay-Zweig und puffert/streamt Nutzdaten über <code>PduR_FrTpCopyTxData()</code>.</li>\n<li><strong>ISO 10681-2 Frame-Generierung:</strong> <code>FrTp</code> fragmentiert die N-SDU in N-PDUs:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Start Frame (SF) bei unsegmentierten Nachrichten.</li>\n<li>First Frame (FF) gefolgt von Consecutive Frames (CF) bei segmentiertem Transfer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfang & Flow Control:</strong> Ziel-ECU (z. B. <code>ECU 1</code>) signalisiert über <code>FrTp_RxIndication()</code> den Eingang, reserviert Puffer über <code>PduR_FrTpStartOfReception()</code> und antwortet bei Bedarf mit Flow Control Frames (FC: CTS, WT, OVFLW) an das Gateway.</li>\n<li><strong>Quittierung:</strong> Nach erfolgreichem Empfang aller CFs meldet <code>FrTp</code> via <code>PduR_FrTpRxIndication(E_OK)</code> den Abschluss an die Diagnose-Applikation (<code>Dcm</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Parallelität & Timer-Überwachung:</strong></li>\n<li>Das Gateway-FrTp betreibt parallele Verbindungszustandsautomaten (Connection Channels), um mehrere ECUs simultan zu bedienen.</li>\n<li>ISO 10681-2 Timer ($A_s$, $A_r$, $B_s$, $B_r$, $C_r$) laufen pro aktivem Kanal autark. Bei Timeout erfolgt der synchrone Verbindungsabbruch und die Fehlermeldung <code>PduR_FrTpRxIndication(E_NOT_OK)</code> bzw. <code>PduR_FrTpTxConfirmation(E_NOT_OK)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Routing-Architektur (<code>PduR</code> / Gateway-Konfiguration):</strong></li>\n<li>Das Gateway muss für paralleles Flashen (<code>Parallel Diagnostic Flashing</code>) konfiguriert sein. Hierfür sind in der Ecuc des Gateways ausreichend viele parallele Kanäle (<code>FrTpNumberOfChannels</code>) und FIFO-/Gateway-Buffer in der <code>PduR</code> vorzuhalten.</li>\n<li><strong>FlexRay-Slot-Allokation (FrIf / Fibex / ARXML):</strong></li>\n<li><code>FrTp</code>-PDUs werden bevorzugt im <strong>dynamischen Segment</strong> des FlexRay-Zyklus über Minislots übertragen, um Bandbreite bedarfsgerecht zuzuweisen, ohne die zyklisch-deterministischen Signale im statischen Segment zu stören.</li>\n<li>Werden statische Slots genutzt, müssen diese für TP exklusiv oder im PDU-Multiplexing reserviert werden.</li>\n<li><strong>Konfigurationsasymmetrie (Gateway vs. Sub-ECUs):</strong></li>\n<li><em>Gateway:</em> Erfordert maximale Pufferkapazität, hohe Kanalanzahl und Reentrancy-Handling für asynchrone Tx/Rx-Transaktionen auf mehreren logischen Kanälen.</li>\n<li><em>ECU 1..n:</em> Zur Ressourceneinsparung auf End-Steuergeräten genügen meist minimal konfigurierte <code>FrTp</code>-Instanzen (Single-Channel oder Dual-Channel für gleichzeitige funktionale und physikalische Diagnoseverbindungen).</li>\n<li><strong>ISO 10681-2 Adressierungs-Parameter:</strong></li>\n<li>Konfiguration von <code>FrTpNode</code> und <code>FrTpConnection</code> erfordert eindeutige Zuordnungen von Local- und Remote-Addresses sowie korrekte Abstimmung von Block Size ($BS$) und Separation Time ($ST_{min}$ bzw. Bandwidth Control $BC$).</li>\n</ul>"}, {"id": "FIG-28a6a58bbf878d1c", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Netzwerk- und Deployment-Topologiediagramm (High-Level System Deployment View).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung der Einsatz- und Vernetzungsszenarien des FlexRay ISO Transport Layers (<code>FrTp</code>, spezifiziert nach ISO 10681-2) im AUTOSAR-Gesamtsystem.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Das Schaubild veranschaulicht die Multi-Knoten-Kommunikation über einen gemeinsamen FlexRay-Kommunikationscluster (Kanal A/B).</li>\n<li>Ein zentrales <strong>Gateway-Steuergerät</strong> bindet heterogene Bordnetz-Bussysteme (angedeutet an der linken Schnittstelle, typischerweise Ethernet/DoIP, CAN/CanTp, weitere FlexRay-Zweige) an und fungiert über die <code>PduR</code> (PDU Router) als zentraler Vermittlungsknoten für transportierte Diagnosedaten (UDS nach ISO 14229-2/-4) oder Flash-/Software-Update-Container.</li>\n<li>Die Steuergeräte <strong><code>ECU 1</code> bis <code>ECU n</code></strong> bilden die transportprotokoll-terminierenden Endpunkte am FlexRay-Bus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten & BSW-Module:</strong></li>\n<li><strong>Gateway:</strong> Zentrales Steuergerät mit Multibus-Anbindung. Beherbergt einen Multi-Channel-fähigen <code>FrTp</code>-Stack sowie PduR-Routingpfade zwischen FrTp und Fremdbus-Transportprotokollen (z. B. <code>DoIP</code> oder <code>CanTp</code>).</li>\n<li><strong>ECU 1, ECU 2, ECU n:</strong> Unabhängige FlexRay-Teilnehmer (Subsysteme/Sensoren/Aktoren), die jeweils eine lokale <code>FrTp</code>-Modulinstanz zur Terminierung von TP-Verbindungen ausführen.</li>\n<li><strong>FlexRay-Bus:</strong> Physikalischer Übertragungskanal (Shared Medium, statisches und/oder dynamisches Segment gemäß FlexRay-Kommunikationszyklus).</li>\n<li><strong>Schnittstellen & Kopplung der FrTp-Module:</strong></li>\n<li><strong>Obere Schnittstelle (PduR-Kopplung):</strong></li>\n<li>Sendepfad: <code>PduR_FrTpTransmit()</code>, <code>PduR_FrTpCopyTxData()</code>, <code>PduR_FrTpTxConfirmation()</code>.</li>\n<li>Empfangspfad: <code>PduR_FrTpStartOfReception()</code>, <code>PduR_FrTpCopyRxData()</code>, <code>PduR_FrTpRxIndication()</code>.</li>\n<li><strong>Untere Schnittstelle (FrIf-Kopplung):</strong></li>\n<li>Sendepfad: <code>FrIf_Transmit()</code>, <code>FrIf_CancelTransmit()</code>.</li>\n<li>Empfangspfad / Callbacks: <code>FrTp_RxIndication()</code>, <code>FrTp_TxConfirmation()</code>, <code>FrTp_TriggerTransmit()</code>.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><strong>Topologie:</strong> $1 : n$-Verbindung (1 Gateway bedient $n$ ECUs über einen gemeinsamen FlexRay-Cluster).</li>\n<li><strong>Kommunikationsbeziehungen:</strong></li>\n<li>Punkt-zu-Punkt (1:1 Unicast) für physikalische Adressierung (z. B. gezieltes Flashen von <code>ECU 1</code>).</li>\n<li>Punkt-zu-Mehrpunkt (1:n Multicast/Broadcast) für funktionale Adressierung (z. B. simultaner Diagnosestatus/TesterPresent an <code>ECU 1..n</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>End-to-End Routing-Szenario (Gateway $\\rightarrow$ ECU x):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Routing-Trigger:</strong> Gateway empfängt eine segmentierte Großnachricht über ein externes Interface (z. B. DoIP via Ethernet).</li>\n<li><strong>Inter-Module Buffering:</strong> <code>PduR</code> im Gateway initiiert via <code>FrTp_Transmit()</code> den Sendeprozess auf dem FlexRay-Zweig und puffert/streamt Nutzdaten über <code>PduR_FrTpCopyTxData()</code>.</li>\n<li><strong>ISO 10681-2 Frame-Generierung:</strong> <code>FrTp</code> fragmentiert die N-SDU in N-PDUs:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Start Frame (SF) bei unsegmentierten Nachrichten.</li>\n<li>First Frame (FF) gefolgt von Consecutive Frames (CF) bei segmentiertem Transfer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Empfang & Flow Control:</strong> Ziel-ECU (z. B. <code>ECU 1</code>) signalisiert über <code>FrTp_RxIndication()</code> den Eingang, reserviert Puffer über <code>PduR_FrTpStartOfReception()</code> und antwortet bei Bedarf mit Flow Control Frames (FC: CTS, WT, OVFLW) an das Gateway.</li>\n<li><strong>Quittierung:</strong> Nach erfolgreichem Empfang aller CFs meldet <code>FrTp</code> via <code>PduR_FrTpRxIndication(E_OK)</code> den Abschluss an die Diagnose-Applikation (<code>Dcm</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Parallelität & Timer-Überwachung:</strong></li>\n<li>Das Gateway-FrTp betreibt parallele Verbindungszustandsautomaten (Connection Channels), um mehrere ECUs simultan zu bedienen.</li>\n<li>ISO 10681-2 Timer ($A_s$, $A_r$, $B_s$, $B_r$, $C_r$) laufen pro aktivem Kanal autark. Bei Timeout erfolgt der synchrone Verbindungsabbruch und die Fehlermeldung <code>PduR_FrTpRxIndication(E_NOT_OK)</code> bzw. <code>PduR_FrTpTxConfirmation(E_NOT_OK)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Routing-Architektur (<code>PduR</code> / Gateway-Konfiguration):</strong></li>\n<li>Das Gateway muss für paralleles Flashen (<code>Parallel Diagnostic Flashing</code>) konfiguriert sein. Hierfür sind in der Ecuc des Gateways ausreichend viele parallele Kanäle (<code>FrTpNumberOfChannels</code>) und FIFO-/Gateway-Buffer in der <code>PduR</code> vorzuhalten.</li>\n<li><strong>FlexRay-Slot-Allokation (FrIf / Fibex / ARXML):</strong></li>\n<li><code>FrTp</code>-PDUs werden bevorzugt im <strong>dynamischen Segment</strong> des FlexRay-Zyklus über Minislots übertragen, um Bandbreite bedarfsgerecht zuzuweisen, ohne die zyklisch-deterministischen Signale im statischen Segment zu stören.</li>\n<li>Werden statische Slots genutzt, müssen diese für TP exklusiv oder im PDU-Multiplexing reserviert werden.</li>\n<li><strong>Konfigurationsasymmetrie (Gateway vs. Sub-ECUs):</strong></li>\n<li><em>Gateway:</em> Erfordert maximale Pufferkapazität, hohe Kanalanzahl und Reentrancy-Handling für asynchrone Tx/Rx-Transaktionen auf mehreren logischen Kanälen.</li>\n<li><em>ECU 1..n:</em> Zur Ressourceneinsparung auf End-Steuergeräten genügen meist minimal konfigurierte <code>FrTp</code>-Instanzen (Single-Channel oder Dual-Channel für gleichzeitige funktionale und physikalische Diagnoseverbindungen).</li>\n<li><strong>ISO 10681-2 Adressierungs-Parameter:</strong></li>\n<li>Konfiguration von <code>FrTpNode</code> und <code>FrTpConnection</code> erfordert eindeutige Zuordnungen von Local- und Remote-Addresses sowie korrekte Abstimmung von Block Size ($BS$) und Separation Time ($ST_{min}$ bzw. Bandwidth Control $BC$).</li>\n</ul>"}], "trans": [{"from": "FIG-e2f7c8e893c8483c", "to": "FIG-ad6a3a0d1fec0690", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ad6a3a0d1fec0690", "to": "FIG-4cced100e5287ece", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4cced100e5287ece", "to": "FIG-28a6a58bbf878d1c", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Gateway (Busschnittstellen):</strong> Der untere Bildausschnitt wurde nach unten erweitert, wodurch die zuvor am Bildrand abgeschnittenen vertikalen Beschriftungen der heterogenen Bussysteme („Ethernet“, „CAN“, „FlexRay“, „LIN“, „…“) vollständig lesbar sind.</li>\n</ul>"}]};
